const t = useTranslate()
const trial = billing.status === "trialing" && billing.trialEndsAt ? { plan: billing.plan, endsAt: billing.trialEndsAt } : undefined
const fimDoTeste = trial ? new Intl.DateTimeFormat(i18n.language, { day: "numeric", month: "short", year: "numeric" }).format(new Date(trial.endsAt)) : ""
const ativa = billing.status === "active"
// o tipo do workspace decide o resto (workspace.kind): no team, Free, Pro e Enterprise, por pessoa; no personal, Free e Pro, só a pessoa
const pessoal = workspace.kind === "personal"
const rotulo = (key: string, plan: string) => ativa && key === billing.plan && billing.period === "monthly" && periodo === "yearly" ? t("platform.billing.plans.cta.switch_yearly") : t(ativa || key === "platform_free" ? "platform.billing.plans.cta.switch" : "platform.billing.plans.cta.subscribe", { plan })
const item = (k: string, params?: Record<string, unknown>) => ({ label: t(`platform.billing.plans.features.${k}`, params) })
const testeItem = trial ? [{ label: t("platform.billing.plans.features.trial", { count: workspace.trialDays }), note: t("platform.billing.plans.features.trial_ends", { date: fimDoTeste }) }] : []
// os números são do admin de planos, no GET /plans: o limite de pessoas (maxMembers, null = sem limite) e o mínimo cobrado (minSeats)
const free = catalogo.find((p) => p.key === "platform_free")!
const pro = catalogo.find((p) => p.key === "platform_pro")!
const enterprise = catalogo.find((p) => p.key === "platform_enterprise")!
// a descrição do cartão, pelo tipo do workspace (platform.billing.plans.description.<plano>.<kind>); o "até {{max}}" é o limite do Pro, do admin
const descricao = (key: string) => t(`platform.billing.plans.description.${key.replace(/^platform_/, "")}.${workspace.kind}`, { max: pro.maxMembers })
const planos: SeatPlan[] = pessoal
  ? // no personal, os planos com o recurso personalAvailable (platform.personal_available do admin, R42), nunca uma lista fixa: hoje Free e Pro
    catalogo
      .filter((p) => p.personalAvailable)
      .map((p) =>
        p.pricePerSeat === null
          ? { key: p.key, name: p.name, description: descricao(p.key), pricePerSeat: null, includesCodePro: false, features: [item("just_you")], footnote: t("platform.billing.plans.footnote.personal", { plan: pro.name }), ctaLabel: rotulo(p.key, p.name) }
          : { key: p.key, name: p.name, description: descricao(p.key), pricePerSeat: p.pricePerSeat, includesCodePro: p.includesCodePro, features: [item("just_you"), ...(trial?.plan === p.key ? testeItem : []), item("yearly_discount")], ctaLabel: rotulo(p.key, p.name) }
      )
  : [
      { key: free.key, name: free.name, description: descricao(free.key), pricePerSeat: null, includesCodePro: false, features: [item("up_to", { count: free.maxMembers })], footnote: t("platform.billing.plans.footnote.team", { max: free.maxMembers, plan: enterprise.name }), ctaLabel: rotulo(free.key, free.name) },
      { key: pro.key, name: pro.name, description: descricao(pro.key), pricePerSeat: pro.pricePerSeat, includesCodePro: pro.includesCodePro, features: [item("up_to", { count: pro.maxMembers }), ...testeItem, item("accepted_invite"), item("yearly_discount")], ctaLabel: rotulo(pro.key, pro.name) },
      { key: enterprise.key, name: enterprise.name, description: descricao(enterprise.key), pricePerSeat: enterprise.pricePerSeat, minSeats: enterprise.minSeats, includesCodePro: enterprise.includesCodePro, contactSales: true, features: [item("unlimited"), item("min_seats", { count: enterprise.minSeats }), item("contract"), item("yearly_discount")], ctaLabel: t("platform.billing.plans.cta.contact_sales") },
    ]
<SeatPlanCards
  plans={planos}
  period={periodo}
  onPeriodChange={setPeriodo}
  currency={moeda}
  onCurrencyChange={billing.currency ? undefined : setMoeda}
  currentPlan={billing.plan}
  trial={trial}
  recommendedPlan="platform_pro"
  // o personal paga 1 assento: "por mês", sem o "por pessoa"
  perSeat={!pessoal}
  onChoose={(key) => {
    // o plano e o período já assinados não fazem nada; o Free é rebaixamento e não passa pelo checkout
    if (!trial && key === billing.plan && (billing.period === undefined || billing.period === periodo)) return
    if (key === "platform_free") return rebaixarParaFree()
    navigate(`/${slug}/billing/checkout?plan=${key}&period=${periodo}`)
  }}
  onContactSales={() => navigate(`/${slug}/billing/sales`)}
  locale={i18n.language}
  loading={carregando}
/>

Os planos são Free, Pro e Enterprise, os mesmos para todo workspace; o tipo (workspace.kind) decide o que aparece: no team, os três cartões (Free e Pro até o limite do plano, o Enterprise sem limite e com o mínimo cobrado); no personal, só os planos com personalAvailable (o recurso platform.personal_available do admin, R42; hoje Free e Pro, sem o Enterprise), sem o limite de pessoas e com perSeat={false} ("por mês" e "por ano", porque o personal paga 1 assento). A grade segue o número de planos (3 colunas do lg, 2 do sm); com dois, o app estreita a página (o canvas usa 760px), para os cartões não esticarem. planos vem de GET /plans (catalogo), na moeda escolhida, mais o que o app escreve com o t(): os itens da lista (platform.billing.plans.features.*, com o limite e o mínimo lidos do plano: up_to { count: maxMembers } e min_seats { count: minSeats }; nada de número fixo, porque o admin muda), a descrição (description.{free,pro,enterprise}.{team,personal}, pelo tipo do workspace, com o { max } do Pro; o Enterprise só tem team), a nota do pé (footnote.team ou footnote.personal, com o nome do plano) e o rótulo do botão (cta.*) são os padrões do i18n, e o componente continua recebendo description, features, footnote e ctaLabel por props. O item "{{count}} dias de teste" (os dias vêm do app, workspace.trialDays, nunca fixos), com a nota "termina em {{date}}", só entra quando o workspace está no teste. Os preços são por pessoa, em centavos, como a API manda: o anual já vem com o desconto e aparece por pessoa/ano, sem dividir por 12; o componente não soma nem desconta (F12). A única conta é o "a partir de R$ 490/mês" do plano com minSeats > 1 (seatPlanFloor: mínimo × preço), só exibição; minSeats é opcional, e ausente, nulo, 0, 1 ou não finito não tem piso. O Code Pro só aparece com includesCodePro (Pro e Enterprise), sempre com "na assinatura paga": o teste não inclui o Code. Moeda: antes da primeira compra (o GET …/billing sem currency), o app escolhe pela região do navegador (BR → BRL, as outras → USD) e passa onCurrencyChange; depois dela, billing.currency trava a moeda, sem onCurrencyChange, e no lugar da troca aparece "Em reais, a moeda da assinatura" com o cadeado. Estado: trial ganha o selo "No teste" (vence o currentPlan), com a data de fim dentro do selo só para o leitor de tela; o workspace que nasceu no Free (o teste é um por pessoa) não passa trial. O botão chama onChoose(key); o plano com contactSales chama onContactSales e nunca o onChoose: sem onContactSales, o botão dele fica desabilitado. O onChoose do app trata o Free (rebaixamento, fora do checkout) e o plano e período já assinados (não faz nada). Carregando: loading mostra as trocas e os cartões em silhueta, um por plano (sem os planos, 3 no team e 2 com perSeat={false}); o SeatPlanCardsSkeleton também sai sozinho: <SeatPlanCardsSkeleton count={pessoal ? 2 : 3} recommendedIndex={1} />. Sem recommendedPlan (ou recommendedIndex -1 ou ausente), nenhum cartão se destaca e a grade não abre os 22px do cartão erguido. Os textos fixos ficam em platform.billing.plans.* do i18n; o app injeta o t.

// ── C2: o checkout (/:slug/billing/checkout?plan=platform_pro&period=monthly; o documento nunca vai na URL) ──
const [periodoCheckout, setPeriodoCheckout] = useState<SeatPlanPeriod>(periodoDaUrl)
const [fiscal, setFiscal] = useState<FiscalValue>({ country: billing.country ?? regiaoDoNavegador, taxId: "", legalName: "" })
const [errosFiscais, setErrosFiscais] = useState<FiscalErrors>({})
const [cupom, setCupom] = useState<CheckoutCoupon["applied"]>(null)
const [erroCupom, setErroCupom] = useState<string>()
const [validandoCupom, setValidandoCupom] = useState(false)
const [indo, setIndo] = useState(false)
const plano = planos.find((p) => p.key === planoDaUrl) // do GET /plans, na moeda do país declarado
// o ?plan= vem da URL: um plano fora dos planos do workspace (o Enterprise no personal, uma chave que não existe) ou sem preço (o Free) volta para os planos
if (!plano?.pricePerSeat) return <Navigate to={`/${slug}/billing/plans`} replace />
const limite = catalogo.find((p) => p.key === planoDaUrl)?.maxMembers ?? null // o limite de pessoas do admin; null no Enterprise
const continuar = async () => {
  // o documento sai do tipo do workspace, não do plano: personal pede o CPF; team, o CNPJ e a razão social
  const locais = fiscalErrors(workspace.kind, fiscal)
  if (Object.keys(locais).length > 0) return setErrosFiscais(locais)
  setIndo(true)
  const brasil = isBrazil(fiscal.country)
  const resposta = await api.checkout({
    plan: planoDaUrl,
    period: periodoCheckout,
    country: fiscal.country,
    taxId: brasil ? fiscal.taxId : undefined,
    legalName: brasil && fiscalDocument(workspace.kind) === "cnpj" ? fiscal.legalName.trim() : undefined,
    coupon: periodoCheckout === "monthly" ? cupom?.code : undefined, // a API recusa cupom no anual (COUPON_INVALID)
  })
  if (resposta.ok) return window.location.assign(resposta.url)
  setIndo(false)
  // o erro da API vence o local e fica no campo
  if (resposta.code === "TAX_ID_REQUIRED") setErrosFiscais({ taxId: "required" })
  if (resposta.code === "TAX_ID_INVALID") setErrosFiscais({ taxId: "invalid" })
  if (resposta.code === "LEGAL_NAME_REQUIRED") setErrosFiscais({ legalName: "required" })
  // 409: a moeda já travou em outra compra, o workspace passou do limite do plano ou o plano não vale para o tipo do workspace (R42); o erro do app na tela, para não ficar calado
  if (resposta.code === "WORKSPACE_CURRENCY_LOCKED" || resposta.code === "MEMBER_LIMIT_REACHED" || resposta.code === "PLAN_NOT_AVAILABLE_FOR_WORKSPACE") mostrarErroGenerico()
}
<CheckoutPage
  kind={workspace.kind}
  planName={plano.name}
  period={periodoCheckout}
  onPeriodChange={(p) => {
    setPeriodoCheckout(p)
    // o cupom só vale no mensal, e o desconto aplicado era do outro período
    setCupom(null)
    setErroCupom(undefined)
  }}
  onSubmit={continuar}
  submitting={indo}
  backRender={<Link to={`/${slug}/billing/plans`} />}
  fiscal={
    <FiscalForm
      kind={workspace.kind}
      value={fiscal}
      onChange={(v) => {
        setFiscal(v)
        setErrosFiscais({})
      }}
      errors={errosFiscais}
      countries={paisesDoStripe}
      locale={i18n.language}
      disabled={indo}
    />
  }
  summary={
    <CheckoutSummary
      plan={{ key: plano.key, name: plano.name }}
      kind={workspace.kind}
      period={periodoCheckout}
      workspaceName={workspace.name}
      people={pessoasAtivas}
      // depois da primeira compra, billing.currency trava a moeda: o país não a troca
      pricePerSeat={{ amountInCents: plano.pricePerSeat[periodoCheckout], currency: billing.currency ?? moedaDoPais }}
      minSeats={plano.minSeats}
      includesCodePro={plano.includesCodePro}
      features={
        workspace.kind === "personal"
          ? [t("platform.billing.plans.features.just_you"), t("platform.billing.plans.features.yearly_discount")]
          : [
              limite === null ? t("platform.billing.plans.features.unlimited") : t("platform.billing.plans.features.up_to", { count: limite }),
              t("platform.billing.plans.features.accepted_invite"),
            ]
      }
      coupon={
        cupomLigado
          ? {
              onApply: async (code) => {
                setValidandoCupom(true)
                // POST /platform/workspaces/:workspaceId/coupons/validate (só o owner; 10 por minuto) { code, plan, period: "monthly", seats, country }
                // → { description, discountInCents, totalInCents, durationInMonths? }: once dá 1, repeating dá os meses, forever vem sem o campo
                // a API leva seats a max(seats, mínimo do plano) e, no personal, a 1; a moeda sai como no checkout (a travada vence o país)
                const r = await api.validateCoupon(workspace.id, { code, plan: planoDaUrl, period: "monthly", seats: pessoasAtivas.length, country: fiscal.country })
                setValidandoCupom(false)
                if (!r.ok && r.status === 422) return setErroCupom(t("…coupon_invalid")) // 422 COUPON_INVALID uniforme
                if (!r.ok) return mostrarErroGenerico() // 429 (10 por minuto) e 503: o erro genérico do app, nunca "cupom inválido"
                setErroCupom(undefined)
                setCupom({ code, description: r.description, discountInCents: r.discountInCents, totalInCents: r.totalInCents, durationInMonths: r.durationInMonths })
              },
              onRemove: () => setCupom(null),
              applied: cupom,
              error: erroCupom,
              pending: validandoCupom,
            }
          : undefined
      }
      locale={i18n.language}
    />
  }
/>

// ── C2: falar com o comercial (/:slug/billing/sales), na mesma moldura; só no workspace team (o personal não tem Enterprise) ──
// o mínimo do Enterprise é do admin (platform.min_seats, no GET /plans): nada de 10 fixo
const minimo = enterprise.minSeats ?? 1
const [pedido, setPedido] = useState<ContactSalesValue>({ seats: minimo, message: "" })
const [mandando, setMandando] = useState(false)
const [enviado, setEnviado] = useState(false)
const enviar = async () => {
  setMandando(true)
  const mensagem = pedido.message.trim()
  const r = await api.salesContact({ seats: pedido.seats!, message: mensagem || undefined }) // 202; 429 é o erro genérico do app
  setMandando(false)
  if (r.ok) setEnviado(true)
}
<BillingPageLayout
  current={t("platform.billing.sales.title")}
  backRender={<Link to={`/${slug}/billing/plans`} />}
  aside={
    <ContactSalesSummary
      plan={{ key: enterprise.key, name: enterprise.name }}
      pricePerSeat={{ amountInCents: enterprise.pricePerSeat!.monthly, currency: billing.currency ?? moedaDoPais }}
      minSeats={minimo}
      seats={pedido.seats}
      includesCodePro={enterprise.includesCodePro}
      email={conta.email}
      sent={enviado}
      locale={i18n.language}
    />
  }
>
  <ContactSalesForm
    value={pedido}
    onChange={setPedido}
    onSubmit={enviar}
    submitting={mandando}
    sent={enviado}
    email={conta.email}
    minSeats={minimo}
    trialEndsAt={billing.status === "trialing" ? billing.trialEndsAt : undefined}
    trialPlanName={pro.name}
    locale={i18n.language}
    backRender={<Link to={`/${slug}/billing/plans`} />}
  />
</BillingPageLayout>

C2. CheckoutPage é a página de assinar, dentro do workspace (nada de Dialog nem Sheet): o caminho "← Planos / Assinar o X / Pagamento no Stripe" (o DS não tem roteador: backRender com o Link do app, ou onBack), o título com o nome do plano (planName), a linha de contexto pelo tipo (kind: no team, "Cada pessoa no workspace ocupa um assento."; no personal, "Um assento: o workspace é só seu."), o período (o mesmo ViewToggle dos cartões), o FiscalForm no slot fiscal, "Continuar para o pagamento" e a nota do Stripe; o resumo vem no slot summary. FiscalForm (CA12): o país primeiro (countries em ISO 3166-1, o nome no Intl.DisplayNames do locale); fora do Brasil, só o país e a nota de que o Stripe pede o número fiscal; no Brasil, o documento sai do tipo do workspace (kind), e não do plano: o CPF no personal e o CNPJ + a razão social (1 a 150, F10) no team. É controlado: value guarda o documento normalizado, sem máscara (o que o onChange devolve, e o que vai no POST), e a máscara entra enquanto a pessoa digita, com o caret no lugar ao editar no meio e o Backspace logo depois de um separador apagando o caractere antes dele; o CNPJ alfanumérico aceita minúsculas e a máscara ao colar. O país é comparado em maiúsculas ("br" é o Brasil), e um código malformado (ex.: "BRA") aparece como veio. errors vem do app (fiscalErrors, antes de mandar) ou da API (TAX_ID_REQUIRED → taxId required, TAX_ID_INVALID → invalid, LEGAL_NAME_REQUIRED → legalName required), e o da API vence. O documento é sensível: autoComplete="off", nunca em URL, query, localStorage, sessionStorage nem log; só no estado da página. tax-id.ts (CA11): normalizeTaxId, sanitizeCpf/sanitizeCnpj (o que cabe no campo), formatCpf/formatCnpj (a máscara, também parcial), isValidCpf (F8, módulo 11) e isValidCnpj (F9/R33: ASCII − 48, os pesos da Receita, resto 0 ou 1 dá DV 0), fiscalDocument(kind), fiscalErrors(kind, valor), isBrazil e countryName. CheckoutSummary: o plano com o ícone e o período, as pessoas ("N pessoas no <workspace> · você + N"; só você, "Só você" e o nome; sem ninguém, só o nome do workspace; com kind="personal", sempre "Só você" e 1 assento), "N pessoas × preço … total" (a única conta, só exibição, como a do SeatsPreview, F12, com N = max(pessoas, minSeats ?? 1), porque a API cobra max(ativos, min_seats)), "Muriki Code Pro … incluso" com includesCodePro e a nota "na assinatura paga" (quem assina no teste fica trialing até o fim dele, e o teste não dá o Code, R37), o cupom e o total. O cupom é o CouponField do onboarding-pricing (link → campo → selo aplicado); sem a prop coupon, não aparece (o app só liga quando a API fechar o B8). O cupom só vale no mensal: a API recusa no anual (422 COUPON_INVALID, period_not_eligible), então no anual o resumo não mostra o campo, a linha nem o total com cupom, e o app limpa o cupom ao trocar o período e só o manda no checkout mensal. Com billing.currency já gravado, o resumo usa essa moeda (o país não troca a moeda). WORKSPACE_CURRENCY_LOCKED, MEMBER_LIMIT_REACHED e PLAN_NOT_AVAILABLE_FOR_WORKSPACE (409; o último é o plano que não vale para o tipo do workspace, R42, como o Enterprise no personal) no checkout viram o erro do app, na tela. O ?plan= da URL que não está nos planos do workspace (ou o Free, sem preço) volta para os planos, sem chegar ao checkout. Aplicado, o desconto e o total com desconto vêm prontos da API (discountInCents e totalInCents): o DS mostra a linha do desconto e o total cheio riscado, e com durationInMonths a nota "nos N primeiros meses; depois, <total>" (o cupom "once" entra como 1 mês; o "forever", sem durationInMonths, não tem nota). ContactSalesForm (CA13): o mínimo do Enterprise vem do plano (minSeats, obrigatório: "cobra no mínimo N" na linha de contexto e na dica), as pessoas com − e + (inteiro de 1 a 100.000; vazio é null e desliga o Enviar) e a mensagem opcional de até 2.000 com o contador do Textarea (showCount, em code points, como a API); sent troca o formulário pela confirmação, com o pedido citado (a mensagem como texto puro) e "Voltar para os planos", e o foco vai para o título dela; com trialEndsAt e trialPlanName, "o teste do Pro segue até …". ContactSalesSummary: o preço por pessoa, o mínimo, a estimativa (N × preço, nunca abaixo do mínimo, só exibição), o contrato, o Code Pro para as pessoas pedidas (cada membro ativo recebe o Code Pro, code-bundle) e "O que acontece depois" em 3 passos, com o passo de agora (sent avança). BillingPageLayout é a moldura comum (o caminho, o formulário à esquerda e a faixa do resumo à direita; abaixo de lg o resumo desce). Os textos ficam em platform.billing.{checkout,fiscal,coupon,sales}.* do i18n (as pessoas do resumo reaproveitam platform.members.seats.title e count). Nenhum componente chama rede.

// ── C3: a página de Cobrança (/:slug/billing), do GET …/billing e dos membros ativos ──
// só do owner: o GET …/billing e o portal do Stripe respondem 403 aos outros papéis, e o app esconde deles a navegação para a Cobrança
// billing = { plan, status, period?, currency?, country?, seats: { active, paid }, trialEndsAt?, subscribed, currentPeriod: { start, end } | null, taxId: { kind, masked } | null, legalName?, nextInvoice: { amountInCents, currency, date } | null, seatChanges: { kind, name, at, prorated }[] }
// status: trialing | free | active | past_due | unpaid | canceled; seats.paid é a quantity do Stripe; datas em ISO com hora
// nextInvoice vem null no Free, no teste sem assinatura e quando o Stripe está fora; nesse último caso, nextInvoiceUnavailable: true (sempre presente) e o resto do resumo responde normalmente
const plano = planos.find((p) => p.key === billing.plan)! // do GET /plans, na moeda do workspace
const fimDoTeste = billing.status === "trialing" ? billing.trialEndsAt : undefined
// o fim do período pago, igual nos dois cartões: o currentPeriod vem mesmo com o Stripe fora (nextInvoice null)
const pagoAte = billing.currentPeriod?.end ?? billing.nextInvoice?.date
const saem = (billing.seatChanges ?? []).filter((m) => m.kind === "leaving").map((m) => ({ name: m.name }))
// o Code Pro pelo direito (R37), não pela feature do plano: active, ou past_due dentro da carência (a API decide), dá o direito;
// trialing, unpaid e canceled num plano com o Code ficam pendentes; o Free não tem
const codePro = !plano.includesCodePro || billing.status === "free" ? undefined : billing.status === "active" || billing.status === "past_due" ? "active" : "pending"
// a API cobra max(ativos, min_seats) (R24/R28): o Enterprise com 6 ativos paga 10
const cobrados = Math.max(billing.seats.active, plano.minSeats ?? 1)
<BillingOverview
  hero={
    <NextInvoiceHero
      plan={{ key: plano.key, name: plano.name }}
      status={billing.status}
      period={billing.period}
      nextInvoice={billing.nextInvoice}
      // o Stripe não respondeu: "Não deu para buscar a próxima cobrança agora." e o "Tentar de novo" (o app busca o resumo de novo)
      nextInvoiceUnavailable={billing.nextInvoiceUnavailable}
      retry={{ onClick: () => recarregarResumo() }}
      // só texto: os assentos cobrados e o preço por pessoa do período; o valor de cima é o nextInvoice da API
      breakdown={plano.pricePerSeat && billing.period ? { seats: cobrados, pricePerSeatInCents: plano.pricePerSeat[billing.period] } : undefined}
      // subscribed: assinou durante o teste (a assinatura paga começa no fim dele)
      trial={fimDoTeste ? { endsAt: fimDoTeste, subscribed: billing.subscribed } : undefined}
      manage={{ onClick: abrirPortalDoStripe }} // o app pede a URL do portal e segue para ela (FE4)
      viewPlans={{ render: <Link to={`/${slug}/billing/plans`} /> }}
      subscribe={{ render: <Link to={`/${slug}/billing/checkout?plan=${billing.plan}&period=monthly`} /> }}
      locale={i18n.language}
    />
  }
  seats={
    <SeatsSummary
      seats={billing.seats}
      people={membrosAtivos.map((m) => ({ id: m.id, name: m.name, you: m.id === conta.id }))} // você primeiro; pode ser só uma página
      leaving={saem}
      paidUntil={pagoAte}
      planName={plano.name}
      minSeats={plano.minSeats}
      codePro={codePro}
      trial={Boolean(fimDoTeste)}
      free={billing.status === "free"}
      // no personal ninguém entra nem sai: sem os avisos do CA10
      personal={workspace.kind === "personal"}
      locale={i18n.language}
    />
  }
  aside={
    <>
      {/* no teste, a conta de quem assinar, acima dos dados fiscais; quem já assinou não a vê */}
      {fimDoTeste && plano.pricePerSeat && !billing.subscribed ? (
        <TrialSubscribeCard
          plan={{ key: plano.key, name: plano.name }}
          people={billing.seats.active}
          pricePerSeat={{ amountInCents: plano.pricePerSeat.monthly, currency: billing.currency ?? moedaDoPais }}
          minSeats={plano.minSeats}
