// ── O passo do convidado (/onboarding/invitee): o @usuário e os termos, SEM workspace, antes do aceite ──
// chega aqui do aceite do convite (409 USERNAME_REQUIRED ou 403 ONBOARDING_REQUIRED) ou de quem acabou de criar a senha pelo convite
// o token do convite e a prévia (POST /platform/invitations/preview) vêm do fluxo do convite, em memória (estado do app): nunca storage nem URL
// ao entrar na rota: GET /onboarding → { products: { platform: "not_started" | "in_progress" | "completed" }, challengeRequired, legalDocuments: { terms, privacy }, … }
// e GET /account/username → { username: string | null } (o @ da conta é um só para todos os produtos: quem vem do Code já tem)
type EntradaDoConvidado = {
  concluido: boolean // o onboarding do Platform já foi concluído: o complete não sai de novo
  versoesDosDocumentos: { terms: string; privacy: string } // as versões que a tela mostra e que o complete declara
  arrobaDaConta: string | null
}
async function lerEntradaDoConvidado(): Promise<EntradaDoConvidado> {
  const [onboarding, conta] = await Promise.all([
    api.get<{ products: { platform: string }; challengeRequired: boolean; legalDocuments: { terms: string; privacy: string } }>("/onboarding"),
    api.get<{ username: string | null }>("/account/username"),
  ])
  const concluido = onboarding.products.platform === "completed"
  // sem a prova da caixa e sem o onboardingToken em memória, o complete responde 403: primeiro o código por e-mail
  // o /onboarding/code (PlatformOnboardingCode) volta para /onboarding/invitee com o token em memória, e o passo vira 2 de 2
  if (onboarding.challengeRequired && !onboardingToken && !concluido) navigate("/onboarding/code")
  return { concluido, versoesDosDocumentos: onboarding.legalDocuments, arrobaDaConta: conta.username }
}
